    $('routeStatus').textContent=state.mode==='cone'?'Exact unfolded surface path':'Route along terrain mesh edges';
    $('profileNote').textContent=state.mode==='cone'?(r.turning?'The route climbs, reaches its highest point, then descends.':'This placement has no interior uphill-to-downhill turning point.'):'Horizontal axis: distance along route (m). Vertical axis: local elevation (m).';
