  for(let j=-5;j<=5;j++){const d=j*ground/5;line([project({x:cx-ground,y:cy+d,z:zmin}),project({x:cx+ground,y:cy+d,z:zmin})],'#264037',.6);line([project({x:cx+d,y:cy-ground,z:zmin}),project({x:cx+d,y:cy+ground,z:zmin})],'#264037',.6);}
