  if(state.route)drawRoute(state.route.points,project);for(const [id,letter,col] of [['a','A',colors.up],['b','B',colors.down]]){const i=n(id+'x'),j=n(id+'y');if(i>=0&&j>=0&&i<t.cols&&j<t.rows)label(project(p(i,j)),letter,col);}
