let pointer=null;canvas.tabIndex=0;canvas.setAttribute('aria-description','Drag or use arrow keys to orbit; plus and minus zoom. Switch to Map to place terrain endpoints.');canvas.addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!pointer||state.view!=='3d')return;state.yaw+=(e.clientX-pointer.x)*.008;state.pitch=Math.max(.1,Math.min(1.4,state.pitch+(e.clientY-pointer.y)*.007));pointer.x=e.clientX;pointer.y=e.clientY;draw();});canvas.addEventListener('pointerup',e=>{if(pointer&&state.view==='2d'&&state.mode==='terrain'&&mapTransform&&Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)<8){const rect=canvas.getBoundingClientRect(),{left,top,scale}=mapTransform,t=state.terrain,i=Math.round((e.clientX-rect.left-left)/scale/t.cellSize),j=Math.round((e.clientY-rect.top-top)/scale/t.cellSize);if(i>=0&&j>=0&&i<t.cols&&j<t.rows){$(state.next.toLowerCase()+'x').value=i;$(state.next.toLowerCase()+'y').value=j;state.next=state.next==='A'?'B':'A';calculate();setView('2d');}}pointer=null;});canvas.addEventListener('pointercancel',()=>pointer=null);canvas.addEventListener('wheel',e=>{if(state.view!=='3d')return;e.preventDefault();state.zoom=Math.max(.5,Math.min(2,state.zoom-e.deltaY*.001));draw();},{passive:false});canvas.addEventListener('keydown',e=>{if(state.view!=='3d')return;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')state.yaw-=.1;if(e.key==='ArrowRight')state.yaw+=.1;if(e.key==='ArrowUp')state.pitch=Math.min(1.4,state.pitch+.1);if(e.key==='ArrowDown')state.pitch=Math.max(.1,state.pitch-.1);if(e.key==='+'||e.key==='=')state.zoom=Math.min(2,state.zoom+.1);if(e.key==='-')state.zoom=Math.max(.5,state.zoom-.1);draw();});
$('settings').addEventListener('submit',e=>{e.preventDefault();calculate();});$('settings').addEventListener('input',e=>{if(e.target.id==='upload')return;if(e.target.id==='angle')$('angleValue').textContent=n('angle')+'°';if(e.target.tagName==='SELECT')return;calculate();});$('settings').addEventListener('change',e=>{if(e.target.id==='upload')return;if(e.target.id==='preset'){syncCustom();['ax','ay'].forEach(id=>$(id).value=2);$('bx').value=n('bx')>Number($('bx').max)?$('bx').max:$('bx').value;$('by').value=n('by')>Number($('by').max)?$('by').max:$('by').value;}calculate();});
$('coneTab').onclick=()=>switchMode('cone');$('terrainTab').onclick=()=>switchMode('terrain');$('view3d').onclick=()=>setView('3d');$('view2d').onclick=()=>setView('2d');$('cameraReset').onclick=()=>{state.yaw=-.78;state.pitch=.4;state.zoom=1;draw();};$('reset').onclick=()=>{$('settings').reset();$('angleValue').textContent='180°';state.next='A';state.yaw=-.78;state.pitch=.4;state.zoom=1;syncCustom();calculate();};['width','thickness','rate','waste'].forEach(id=>$(id).addEventListener('input',updateEstimate));
$('upload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Height maps must be smaller than 2 MB.');state.custom=validateTerrain(JSON.parse(await file.text()));$('preset').querySelector('[value=custom]').disabled=false;$('preset').value='custom';syncCustom();$('ax').value=0;$('ay').value=0;$('bx').value=state.custom.cols-1;$('by').value=state.custom.rows-1;calculate();}catch(err){clearResult('Import failed. '+err.message);}finally{e.target.value='';}});
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>{const r=state.route;if(!r)return;const rows=['distance_m,x_m,y_m,elevation_m',...r.points.map(p=>[p.s,p.x,p.y,p.z].map(v=>v.toFixed(6)).join(','))];download(rows.join('\n')+'\n','terrapath-'+state.mode+'-route.csv','text/csv');};
new ResizeObserver(sizeCanvas).observe(canvas);switchMode('cone');
